export function getDetectiveSentences(levelId, dayId) {
  const entry = GRAMMAR_DETECTIVE_BANK[levelId]?.[dayId]
  if (!entry) return null
  if (Array.isArray(entry[0])) return entry.flat()
  return entry
}
